knappe_produkte = []

with open("bestand.txt", "r", encoding="utf-8") as datei:
    for zeile in datei:
        name, menge = zeile.strip().split(";")
        if int(menge) < 10:
            knappe_produkte.append(name)

with open("knapp.txt", "w", encoding="utf-8") as datei:
    for name in knappe_produkte:
        datei.write(name + "\n")

print("Knapp im Bestand:", len(knappe_produkte))

