hohe_rechnungen = []

with open("rechnungen.txt", "r", encoding="utf-8") as datei:
    for zeile in datei:
        name, betrag = zeile.strip().split(";")
        if float(betrag) > 100:
            hohe_rechnungen.append(name)

with open("hohe_rechnungen.txt", "w", encoding="utf-8") as datei:
    for name in hohe_rechnungen:
        datei.write(name + "\n")

print("Hohe Rechnungen:", len(hohe_rechnungen))
